//! Saved-model package selection -> retained dependency -> real source-hidden game.
#![cfg(all(feature="room-character",feature="project-create",feature="project-export",target_os="linux"))]
use orr_sample::{project_create::{create,CreateOptions},room_project::PreparedProject};
use orr_package::{Project,Lock,PackagePreview};
use sha2::{Digest,Sha256};
use std::{collections::BTreeMap,fs,path::{Path,PathBuf},process::Command};
fn files(root:&Path)->BTreeMap<PathBuf,Vec<u8>> {fn walk(root:&Path,path:&Path,out:&mut BTreeMap<PathBuf,Vec<u8>>) {for e in fs::read_dir(path).unwrap() {let e=e.unwrap();let p=e.path();assert!(!e.file_type().unwrap().is_symlink());if e.file_type().unwrap().is_dir() {walk(root,&p,out);}else{out.insert(p.strip_prefix(root).unwrap().to_path_buf(),fs::read(p).unwrap());}}}let mut out=BTreeMap::new();walk(root,root,&mut out);out}
#[test]
#[ignore="explicit compiled package tool and Room runtime required"]
fn saved_room_model_dependency_is_kept_after_parent_removal_and_runs_from_hidden_source_export() {
    let temp=tempfile::tempdir().unwrap();let root=temp.path().canonicalize().unwrap().join("saved dependency room");create(&CreateOptions {output:root.clone(),template:"room-escape-3d-v1".into(),seed:"keep-model-dependency".into()}).unwrap();
    let runtime=orr_sample::room_project::compiled_runtime();let p=Project::open(&root,runtime).unwrap();let base=p.verify().unwrap();let model="sample-imported-scene";let version=base.packages[model].manifest.version.clone();let prepared=PreparedProject::open(&root).unwrap();let initial=prepared.scene().frame().to_bytes();assert!(prepared.models().document.bindings.values().all(|binding|binding.package==model));
    let source=temp.path().join("level set source");fs::create_dir(&source).unwrap();let deps:BTreeMap<_,_>=[(model,version.as_str())].into_iter().collect();fs::write(source.join("orr.package.json"),serde_json::to_vec(&serde_json::json!({"schema":1,"name":"level-set","version":"1.0.0","engine":"^0.0.1","capabilities":[],"dependencies":deps,"files":["LICENSE.txt"]})).unwrap()).unwrap();fs::write(source.join("LICENSE.txt"),"User test fixture license").unwrap();p.install(std::slice::from_ref(&source)).unwrap();let indirect=p.remove(model).unwrap();assert!(!indirect.direct.contains_key(model));assert_eq!(PreparedProject::open(&root).unwrap().scene().frame().to_bytes(),initial);fs::rename(&source,source.with_extension("hidden")).unwrap();let before=files(&root);
    let tool=PathBuf::from(std::env::var_os("ORR_KEEP_PACKAGE_TOOL").expect("explicit built package tool"));let output=Command::new(&tool).arg("keep").arg(&root).args([model,"--dry-run"]).output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let preview:PackagePreview=serde_json::from_slice(&output.stdout).unwrap();assert_eq!(preview.previous,indirect);assert_eq!(preview.candidate.packages,indirect.packages);assert_eq!(files(&root),before);
    let output=Command::new(&tool).arg("keep").arg(&root).arg(model).output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let kept:Lock=serde_json::from_slice(&output.stdout).unwrap();assert_eq!(kept,preview.candidate);assert_eq!(p.verify().unwrap(),kept);
    let remove=p.preview_remove("level-set").unwrap();p.remove_checked("level-set",&remove.previous,&remove.candidate,|| {PreparedProject::open(&root).map(|_|())}).unwrap();assert_eq!(p.verify().unwrap(),base);let mut after=files(&root);after.insert(PathBuf::from("orr.packages.lock.json"),before[Path::new("orr.packages.lock.json")].clone());assert_eq!(after,before);
    let prepared=PreparedProject::open(&root).unwrap();assert_eq!(prepared.scene().frame().to_bytes(),initial);let mut sim=prepared.scene().simulation().unwrap();for _ in 0..8 {let mut input=orr_sim::TickInputs::new(sim.tick()+1,1);input.set_input(orr_sim::PlayerSlot(0),orr_sample::room_game::RoomInput {move_x:1,..Default::default()});sim.step(&input);}let expected_tick=format!("room tick: 8 checksum: 0x{:016x}",sim.frame().checksum());
    let original=PathBuf::from(std::env::var_os("ORR_KEEP_ROOM_RUNTIME").expect("explicit built Room runtime"));let copied=temp.path().join("trusted Room runtime");fs::copy(original,&copied).unwrap();let hash:String=Sha256::digest(fs::read(&copied).unwrap()).iter().map(|b|format!("{b:02x}")).collect();let bundle=temp.path().join("deployed retained model");orr_sample::project_export::export_room(&orr_sample::project_export::ExportOptions {project:root.clone(),runtime:copied.clone(),runtime_sha256:hash,output:bundle.clone(),trusted_runtime:true,source_revision:None}).unwrap();assert_eq!(Project::open(bundle.join("project"),orr_sample::room_project::compiled_runtime()).unwrap().verify().unwrap(),base);
    fs::rename(&root,root.with_extension("hidden")).unwrap();fs::rename(&copied,copied.with_extension("hidden")).unwrap();let empty=temp.path().join("empty cwd");fs::create_dir(&empty).unwrap();let output=Command::new(bundle.join("run-room-escape")).current_dir(empty).args(["--headless","--ticks","8","--hold","right","--check-model-poses"]).env_remove("DISPLAY").env_remove("WAYLAND_DISPLAY").output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let text=String::from_utf8(output.stdout).unwrap();assert!(text.contains(&expected_tick));assert!(text.contains("room model poses: 9 frames checked;"));
}
